mapper.select:
SELECT run_id, user_id, conversation_id, status, current_step, total_steps,
       plan_json, result, error_code, error_message, created_at, updated_at
FROM ai_task_run
WHERE user_id = #{userId}
  AND run_id = #{runId}

mapper.update:
UPDATE ai_task_run
SET status = 'RUNNING', updated_at = now(), error_code = NULL, error_message = NULL
WHERE user_id = #{userId}
  AND run_id = #{runId}
  AND (
      status IN ('PENDING', 'FAILED', 'PARTIAL_FAILED')
      OR (status = 'RUNNING'
          AND updated_at < now() - make_interval(secs => #{staleSeconds}))
  )

UPDATE ai_task_run
SET status = 'SUCCEEDED', current_step = total_steps, result = #{result},
    error_code = NULL, error_message = NULL, updated_at = now()
WHERE user_id = #{userId}
  AND run_id = #{runId}
  AND status IN ('RUNNING', 'PENDING', 'PARTIAL_FAILED', 'FAILED')

UPDATE ai_task_run
SET status = #{status}, current_step = #{currentStep}, error_code = #{errorCode},
    error_message = #{errorMessage}, result = #{result}, updated_at = now()
WHERE user_id = #{userId}
  AND run_id = #{runId}
  AND status IN ('RUNNING', 'PENDING', 'PARTIAL_FAILED', 'FAILED')

UPDATE ai_task_run
SET status = 'CANCELLED', updated_at = now()
WHERE user_id = #{userId}
  AND run_id = #{runId}
  AND status IN ('PENDING', 'FAILED', 'PARTIAL_FAILED')

UPDATE ai_task_run
SET status = 'CANCELLED', updated_at = now()
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND status = 'PENDING'
